-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): waterflood.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/waterflood.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- INTERMEDIATE
--   TIGHTEN hall_ratio_e4 (expected 1.4285714285714286) tol 0.002 -> 0.0005:
--       the Stiles capacity ratio tile 1.4304 on the default Design view sits 0.0018
--       off and passed; the exact 10/7 route is untouched
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves:
-- waterflood/intermediate. Before it writes, the file counts
-- academy_capstone_attempts on each and REFUSES if any exist, unless D5
-- allowlists that tier with the exact attempt ids (allowlist: empty). Stored
-- scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- waterflood / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'waterflood' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 waterflood refused: waterflood/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd89caf9ab31ed7a175cb909ccf246b12' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.002, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb then 'old'
              when md5(prompt) = 'd89caf9ab31ed7a175cb909ccf246b12' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb then 'new'
              when md5(prompt) = '86d604bff13f405a61ea14ab3aba8f67' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'waterflood' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w1 waterflood refused: waterflood/intermediate matches neither its published form (prompt md5 d89caf9ab31ed7a175cb909ccf246b12) nor its W1 form (prompt md5 d89caf9ab31ed7a175cb909ccf246b12), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 waterflood: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 waterflood refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'waterflood' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'waterflood/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'waterflood/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 waterflood refused: waterflood/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 waterflood: waterflood/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 waterflood refused: waterflood/intermediate holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Take the Ekene flood apart by geometry. The allocation matrix routes Ekene-2 to Ekene-6 0.45, Ekene-1 0.30 and Ekene-3 0.15, and Ekene-4 to Ekene-3 0.40, Ekene-6 0.35 and Ekene-5 0.10. The two elements are North, holding Ekene-1 and Ekene-6, and South, holding Ekene-3 and Ekene-5. Report the injected volume that lands on no producer, each element''s cumulative VRR on the frozen factor set, and the injection recommended for the South element at a target VRR of 1.0 over a three-period trailing window, scaled from the ALLOCATED injection into that element. Then two diagnostics on the raw well data: the Hall plot slope ratio for Ekene-4 built on pressure ABOVE the 2050 psia injection reference, and the late-time log-log slope of the water oil ratio derivative for Ekene-6.',
           fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb
     where app_slug = 'waterflood' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 waterflood refused: waterflood/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd89caf9ab31ed7a175cb909ccf246b12' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb)
        or (md5(prompt) = '86d604bff13f405a61ea14ab3aba8f67' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb) from public.academy_capstones where app_slug = 'waterflood' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 waterflood refused: waterflood/intermediate does not read back as its W1 form';
  end if;

  raise notice 'w1 waterflood: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
